terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  type    = string
  default = "us-east-1"
}

locals {
  default_tags = {
    Owner       = "iac-eval"
    Environment = "dev"
    CostCenter  = "1234"
  }
}

# Create a unique name for the S3 bucket
resource "random_id" "suffix" {
  byte_length = 4
}

# Create an IAM service-linked role
resource "aws_iam_service_linked_role" "eb_ec2_role" {
  aws_service_name = "elasticbeanstalk.amazonaws.com"
  custom_suffix    = "${random_id.suffix.hex}"
}

# Create an IAM instance profile
resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name        = "eb_ec2_profile-${random_id.suffix.hex}"
  role        = aws_iam_service_linked_role.eb_ec2_role.id
  depends_on = [aws_iam_service_linked_role.eb_ec2_role]
}

# Create an S3 bucket
resource "aws_s3_bucket" "examplebucket" {
  bucket = "examplebucket-${random_id.suffix.hex}"
  acl    = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

# Create an S3 object
resource "aws_s3_bucket_object" "examplebucket_object" {
  bucket = aws_s3_bucket.examplebucket.id
  key    = "examplebucket_object"
  acl    = "private"
  source = "path/to/examplebucket_object"
}

# Create an Elastic Beanstalk environment
resource "aws_elastic_beanstalk_environment" "eb-env" {
  name                = "eb-env-${random_id.suffix.hex}"
  application         = "myapp"
  version_label       = "version"
  description         = "Example Elastic Beanstalk environment"
  tier                 = "WebServer"
}

# Create an IAM policy for the Elastic Beanstalk environment
resource "aws_iam_policy" "eb_policy" {
  name        = "eb_policy-${random_id.suffix.hex}"
  description = "Policy for Elastic Beanstalk environment"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "VisualEditor0"
        Effect    = "Allow"
        Action    = ["elasticbeanstalk:CreateEnvironment", "elasticbeanstalk:UpdateEnvironment"]
        Resource = "*"
      },
    ]
  })
}

# Create an IAM role for the Elastic Beanstalk environment
resource "aws_iam_role" "eb_role" {
  name        = "eb_role-${random_id.suffix.hex}"
  description = "Role for Elastic Beanstalk environment"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "VisualEditor0"
        Effect    = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "eb_attach" {
  role       = aws_iam_role.eb_role.id
  policy_arn = aws_iam_policy.eb_policy.arn
}

# Create a Route 53 zone
resource "aws_route53_zone" "main" {
  name = "main-${random_id.suffix.hex}"
}

# Create a Route 53 record set
resource "aws_route53_record" "eb_record" {
  zone_id = aws_route53_zone.main.zone_id
  name    = aws_elastic_beanstalk_environment.eb-env.cname
  type    = "CNAME"
  ttl     = "300"
  records = [aws_elastic_beanstalk_environment.eb-env.cname]
}
