  region = var.region
}

variable "region" {
  type    = string
  default = "us-east-1"
}

locals {
  default_tags = {
    Owner       = "iac-eval"
    Environment = "dev"
    CostCenter  = "1234"
  }
}

# Create an instance profile for Elastic Beanstalk
resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.role.name
}

resource "aws_iam_role" "role" {
  name               = "eb_ec2_role"
  path               = "/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# Create a database for the production environment
resource "aws_db_instance" "prod_db" {
  identifier            = "metricbeat-test-prod-${random_id.suffix1.hex}"
  allocated_storage     = 20
  engine                = "mysql"
  instance_class        = "db.t2.micro"
  db_name               = "metricbeattest"
  username              = "dbadmin"
  password              = random_password.db.result
  storage_encrypted     = true
  publicly_accessible   = false
  skip_final_snapshot   = true
  auto_minor_version_upgrade = true

  tags = local.default_tags
}

# Create a database for the staging environment
resource "aws_db_instance" "stg_db" {
  identifier            = "metricbeat-test-stg-${random_id.suffix2.hex}"
  allocated_storage     = 20
  engine                = "mysql"
  instance_class        = "db.t2.micro"
  db_name               = "metricbeattest"
  username              = "dbadmin"
  password              = random_password.db.result
  storage_encrypted     = true
  publicly_accessible   = false
  skip_final_snapshot   = true
  auto_minor_version_upgrade = true

  tags = local.default_tags
}

resource "aws_elastic_beanstalk_environment" "prod_env" {
  name                = "prod-env"
  application         = aws_elastic_beanstalk_application.app.name
  tier                = "WebServer"
}

resource "aws_elastic_beanstalk_environment" "stg_env" {
  name                = "stg-env"
  application         = aws_elastic_beanstalk_application.app.name
  tier                = "Worker"
}

resource "aws_elastic_beanstalk_application" "app" {
  name        = "metricbeat-test-app"
  description = "metricbeat-test-app"
}

resource "random_id" "suffix1" {
  byte_length = 4
}

resource "random_id" "suffix2" {
  byte_length = 4
}

resource "random_password" "db" {
  length  = 16
  special = false
}
