# Create IAM Role for Lex Bot
resource "aws_iam_role" "lex_bot_role" {
  name        = "lex-bot-role"
  description = "Role for Lex Bot"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lex.amazonaws.com"
        }
      }
    ]
  })

  tags = local.default_tags
}

# Create IAM Policy for Lex Bot
resource "aws_iam_policy" "lex_bot_policy" {
  name        = "lex-bot-policy"
  description = "Policy for Lex Bot"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "lex:CreateBot",
          "lex:CreateBotAlias",
          "lex:PutBot",
          "lex:PutBotAlias",
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })

  tags = local.default_tags
}

# Attach IAM Policy to Role
resource "aws_iam_role_policy_attachment" "lex_bot_attach" {
  role       = aws_iam_role.lex_bot_role.name
  policy_arn = aws_iam_policy.lex_bot_policy.arn
}

# Create Lex Bot
