    zone_id                = "ZONE_ID"  # You'll need to replace this with your zone ID
    evaluate_target_health = true
  }
}

# Add this to ensure the records are created after the health checks
resource "aws_route53_record_set" "primary" {
  depends_on = [aws_route53_health_check.primary_health_check]
}

resource "aws_route53_record_set" "secondary" {
  depends_on = [aws_route53_health_check.secondary_health_check]
