  }
}

# Create an S3 bucket for Terraform state management
resource "aws_s3_bucket" "tf_state" {
  bucket = "my-terraform-state"
  acl    = "private"

  # Prevent accidental bucket deletion
  lifecycle {
    prevent_destroy = true
  }

  # Enable versioning
  versioning {
    enabled = true
  }

  # Enable server-side encryption using AES256
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  # Restrict public access
  acl = "private"

  tags = local.default_tags
}

# Create a DynamoDB table for Terraform locking
resource "aws_dynamodb_table" "tf_lock" {
  name         = "terraform-lock"
  billing_mode = "PAY_PER_REQUEST"

  # Create a hash key named 'LockID'
  attribute {
    name = "LockID"
    type = "S"
  }

  tags = local.default_tags
}
