The error message indicates that there is a conflict between the `metric_name`, `namespace`, `period`, and `statistic` arguments in the `aws_cloudwatch_metric_alarm` resource and the `metric_query` block. This is because the `metric_query` block is trying to override the values specified in the `metric_name`, `namespace`, `period`, and `statistic` arguments.

To fix this, we need to remove the `metric_query` block and specify the metric name, namespace, period, and statistic in the `aws_cloudwatch_metric_alarm` resource.

Here is the corrected Terraform HCL:

```hcl
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.0" }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  type    = string
  default = "us-east-1"
}

locals {
  default_tags = {
    Owner       = "iac-eval"
    Environment = "dev"
    CostCenter  = "1234"
  }
}

resource "aws_cloudwatch_metric_alarm" "promql_alarm" {
  alarm_name        = "high-cpu-promql"
  alarm_description = "Alarm when average CPU exceeds 80% using PromQL"

  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = 2
  metric_name         = "CPUUtilization"
  namespace           = "AWS/EC2"
  period              = 120
  statistic           = "Average"
  threshold           = 80

  actions_enabled = true
  alarm_actions   = [aws_sns_topic.alerts.arn]

  tags = local.default_tags
}

resource "aws_sns_topic" "alerts" {
  name = "alerts"
}

resource "aws_sns_topic_subscription" "alerts_email" {
  topic_arn = aws_sns_topic.alerts.arn
  protocol  = "email"
  endpoint  = "example@example.com"
}

resource "aws_sns_topic_subscription" "alerts_sns" {
  topic_arn = aws_sns_topic.alerts.arn
  protocol  = "email"
  endpoint  = "example@example.com"
}
```

This corrected configuration should now deploy successfully.

