# EFS file system mount
resource "null_resource" "efs_mount" {
  depends_on = [aws_instance.linux_a, aws_instance.linux_b]

  connection {
    type        = "ssh"
    host        = aws_instance.linux_a.public_ip
    user        = "ec2-user"
    private_key = aws_key_pair.ssh_key.id
  }

  provisioner "remote-exec" {
    inline = [
      "sudo mkfs.ext4 /dev/sdh1",
      "sudo mount /dev/sdh1 /mnt"
    ]
  }
}

data "aws_ami" "latest_aws_linux" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm*"]
  }
}

resource "aws_key_pair" "ssh_key" {
  key_name   = "my_key"
  public_key = trimspace(file("~/.ssh/my_key.pub"))
}

output "public_ip_linux_a" {
  value       = aws_instance.linux_a.public_ip
  description = "The public IP address of the first Linux instance."
}

output "public_ip_linux_b" {
  value       = aws_instance.linux_b.public_ip
  description = "The public IP address of the second Linux instance."
}
```

