# Create an IAM role for ElastiCache
resource "aws_iam_role" "elasticache_role" {
  name               = "elasticache-execution-role"
  description        = "Execution role for ElastiCache"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticache.amazonaws.com"
        }
      }
    ]
  })
  tags = local.default_tags
}

# Attach policy to the IAM role
resource "aws_iam_policy" "elasticache_policy" {
  name        = "elasticache-execution-policy"
  description = "Policy for ElastiCache execution"
  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "elasticache:*",
          "kms:*",
          "ec2:*"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "elasticache_attach" {
  role       = aws_iam_role.elasticache_role.name
  policy_arn = aws_iam_policy.elasticache_policy.arn
}

# Create an IAM user for ElastiCache
resource "aws_iam_user" "elasticache_user" {
  name          = "elasticache-execution-user"
  force_destroy = true
  tags          = local.default_tags
}

# Attach IAM role to the IAM user
resource "aws_iam_user_policy_attachment" "elasticache_attach" {
  user       = aws_iam_user.elasticache_user.name
  policy_arn = aws_iam_policy.elasticache_policy.arn
}

# Create an ElastiCache user with IAM authentication
resource "aws_elasticache_user" "test" {
  user_id       = aws_iam_user.elasticache_user.id
  user_name     = aws_iam_user.elasticache_user.name
  access_string = "on ~* +@all"
  engine        = "redis"

  authentication_mode {
    type      = "iam"
  }
}
