  statement {
    actions = ["ec2:DescribeAvailabilityZones"]

    resources = ["*"]
  }
}

resource "aws_iam_policy" "MSK-Serverless-Cluster-Role" {
  name        = "MSK-Serverless-ClusterRolePolicy"
  description = "Policy for MSK Serverless Cluster"
  policy      = <<EOF
  ${data.aws_iam_policy_document.MSK-Serverless-Cluster-Role.jsonencode()}
EOF
}

resource "aws_iam_role" "MSK-Serverless-ClusterRole" {
  name               = "MSK-Serverless-ClusterRole"
  description        = "Role for MSK Serverless Cluster"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "MSK-Serverless-Cluster-Role-Attachment" {
  role       = aws_iam_role.MSK-Serverless-ClusterRole.name
  policy_arn = aws_iam_policy.MSK-Serverless-Cluster-Role.arn
}

data "aws_availability_zones" "azs" {
  state = "available"
}

resource "aws_subnet" "example" {
  count             = 3
  availability_zone = data.aws_availability_zones.azs.names[count.index]
  cidr_block        = "10.0.0.${count.index}.0/24"
  vpc_id            = aws_vpc.example.id

  tags = local.default_tags
}

resource "aws_security_group" "example" {
  vpc_id = aws_vpc.example.id

  tags = local.default_tags
}

resource "aws_msk_serverless_cluster" "example" {
  cluster_name = "serverless-cluster"

  vpc_config {
    subnet_ids         = aws_subnet.example[*].id
    security_group_ids = [aws_security_group.example.id]
  }

  client_authentication {
    sasl {
      iam {
        enabled = true
      }
    }
  }

  tags = local.default_tags
}
