  description = "IAM role for Neptune Cluster"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "neptune.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "neptune-cluster-policy-attachment" {
  role       = aws_iam_role.neptune-cluster-role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonNeptuneFullAccess"
}

