```hcl
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.0" }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  type    = string
  default = "us-east-1"
}

locals {
  default_tags = {
    Owner       = "iac-eval"
    Environment = "dev"
    CostCenter  = "1234"
  }
}

# Define a Neptune subnet group
resource "aws_neptune_subnet_group" "example" {
  name        = "example-neptune-subnet-group"
  description = "Neptune subnet group for example cluster"
  subnet_ids  = [aws_subnet.example[0].id, aws_subnet.example[1].id]
  tags        = local.default_tags
}

resource "aws_subnet" "example" {
  count             = 2
  cidr_block        = cidrsubnet("10.0.0.0/16", 8, count.index)
  vpc_id            = aws_vpc.example.id
  availability_zone = element(aws_availability_zones.current.names, count.index)
  tags              = local.default_tags
}

resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
  tags       = local.default_tags
}

# Define a custom parameter group
resource "aws_neptune_cluster_parameter_group" "example" {
  name        = "custom-parameter-group"
  description = "Custom parameter group for Neptune cluster"
  family      = "neptune1"

  parameter {
    name  = "neptune_enable_audit_log"
    value = 1
  }

  parameter {
    name  = "neptune_enable_slow_query_log"
    value = 1
  }
}

# Define a Neptune cluster with the custom parameter group
resource "aws_neptune_cluster" "example" {
  cluster_identifier = "example-neptune-cluster"
  neptune_cluster_parameter_group_name = aws_neptune_cluster_parameter_group.example.name
  neptune_subnet_group_name        = aws_neptune_subnet_group.example.name
  engine                            = "neptune"
  instance_class                    = "db.t2.micro"
  port                              = 8182
  publicly_accessible               = false
  skip_final_snapshot               = true
  tags                              = local.default_tags
}

# Define a Neptune instance
resource "aws_neptune_cluster_instance" "example" {
  neptune_cluster_identifier = aws_neptune_cluster.example.id
  instance_class             = aws_neptune_cluster.example.instance_class
  port                       = aws_neptune_cluster.example.port
  publicly_accessible        = aws_neptune_cluster.example.publicly_accessible
}

# Define a security group that allows connection only from the two example subnets
resource "aws_security_group" "example" {
  name        = "example-neptune-sg"
  description = "Security group for example Neptune cluster"
  vpc_id      = aws_vpc.example.id

  ingress {
    description = "Allow connection from the two example subnets"
    from_port   = 8182
    to_port     = 8182
    protocol    = "tcp"
    cidr_blocks = [aws_subnet.example[0].cidr_block, aws_subnet.example[1].cidr_block]
  }
}
```

