terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.0" }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  type    = string
  default = "us-east-1"
}

locals {
  default_tags = {
    Owner       = "iac-eval"
    Environment = "dev"
    CostCenter  = "1234"
  }
}

# Create a VPC
resource "aws_vpc" "default" {
  cidr_block = "10.0.0.0/16"
  tags       = local.default_tags
}

# Create a subnet for the instance to connect from
resource "aws_subnet" "example" {
  vpc_id            = aws_vpc.default.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"
  tags              = local.default_tags
}

# Create a security group for the instance
resource "aws_security_group" "example" {
  vpc_id = aws_vpc.default.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 8182
    to_port     = 8182
    protocol    = "tcp"
    cidr_blocks = [aws_subnet.example.cidr_block]
  }
}

# Create a Neptune Cluster
resource "aws_neptune_cluster" "example" {
  cluster_identifier = "neptune-cluster-example"
  skip_final_snapshot = true
  tags               = local.default_tags
}

# Create a custom parameter group for the cluster
resource "aws_neptune_cluster_parameter_group" "cluster_example" {
  name        = "example-neptune-parameter-group"
  family      = "neptune1"
  description = "Example Neptune parameter group"

  parameter {
    name  = "neptune_enable_audit_log"
    value = 1
  }

  parameter {
    name  = "neptune_audit_log_bucket"
    value = "example-neptune-audit-log-bucket"
  }
}

# Create a Neptune instance in the cluster
resource "aws_neptune_cluster_instance" "example" {
  cluster_identifier       = aws_neptune_cluster.example.id
  instance_class           = "db.r5.large"
  parameter_group_name     = aws_neptune_cluster_parameter_group.cluster_example.name
  neptune_cluster_identifier = aws_neptune_cluster.example.id
  tags                     = local.default_tags
}
```

