terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.0" }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  type    = string
  default = "us-east-1"
}

locals {
  default_tags = {
    Owner       = "iac-eval"
    Environment = "dev"
    CostCenter  = "1234"
  }
}

# Create S3 bucket to store code build output
resource "aws_s3_bucket" "codebuild_output" {
  bucket = "codebuild-output-bucket"

  # Enable server-side encryption
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  # Block public access
  # Note: Using aws_s3_bucket_policy to configure public access
  # See https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/s3_bucket_policy

  versioning {
    enabled = true
  }

  logging {
    target_bucket = aws_s3_bucket.codebuild_output.id
    target_prefix = "log/"
  }

  tags = local.default_tags
}

# Create S3 bucket policy to block public access
resource "aws_s3_bucket_policy" "codebuild_output" {
  bucket = aws_s3_bucket.codebuild_output.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "BlockPublicAccess"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource  = "${aws_s3_bucket.codebuild_output.arn}/*"
      }
    ]
  })
}

# Create CodeBuild project
resource "aws_codebuild_project" "codebuild_project" {
  name         = "codebuild-project"
  description  = "CodeBuild project to build students' code"
  source         {
    type        = "GITHUB"
    location    = "github.com/source-location"
    git_clone_depth = 1
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "alpine"
    type                        = "LINUX_CONTAINER"
  }

  artifacts {
    type = "S3"
    location = aws_s3_bucket.codebuild_output.id
  }

  service_role = "arn:aws:iam::123456789012:role/service-role/CodeBuildServiceRole"

  # Specify restrictions for the batch build
  batch_config {
    combine_artifacts = true

    restrictions {
      compute_types_allowed = ["BUILD_GENERAL1_SMALL"]
    }

    timeout_in_minutes = 60
  }

  tags = local.default_tags
}
