        Effect    = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.log_bucket.arn}/logs/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-source-arn" = aws_s3_bucket.pictures.arn
          }
        }
      },
    ]
  })
}

