    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  type    = string
  default = "us-east-1"
}

locals {
  default_tags = {
    Owner       = "iac-eval"
    Environment = "dev"
    CostCenter  = "1234"
  }
}

# Declare the data resource aws_caller_identity
data "aws_caller_identity" "current" {}

# Create EventBridge Rule
resource "aws_cloudwatch_event_rule" "daily_run" {
  name        = "daily-run"
  description = "Run a code every day at 7 UTC"

  schedule_expression = "cron(0 7 * * ? *)"
}

# Create EventBridge Target
resource "aws_cloudwatch_event_target" "lambda_target" {
  target_id = "LambdaTarget"
  rule      = aws_cloudwatch_event_rule.daily_run.name
  arn       = aws_lambda_function.code.arn

  input = jsonencode({
    FunctionName = aws_lambda_function.code.function_name
  })
}

# Create Lambda Function
resource "aws_lambda_function" "code" {
  filename      = "index.zip"
  function_name = "daily-code-run"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn

  environment {
    variables = {
      CODE_NAME = "daily-code-run"
    }
  }
}

# Create IAM Role for Lambda
resource "aws_iam_role" "lambda_exec" {
  name        = "daily-code-run-exec"
  description = "Execution role for the daily code run Lambda function"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      },
    ]
  })
}

# Create IAM Policy for Lambda
resource "aws_iam_policy" "lambda_policy" {
  name        = "daily-code-run-policy"
  description = "Policy for the daily code run Lambda function"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "logs:CreateLogGroup"
        Effect = "Allow"
        Resource = "arn:aws:logs:${var.region}:${data.aws_caller_identity.current.account_id}:*"
      },
      {
        Action = "logs:CreateLogStream"
        Effect = "Allow"
        Resource = "arn:aws:logs:${var.region}:${data.aws_caller_identity.current.account_id}:*"
      },
      {
        Action = "logs:PutLogEvents"
        Effect = "Allow"
        Resource = "arn:aws:logs:${var.region}:${data.aws_caller_identity.current.account_id}:*"
      },
    ]
  })
}

# Attach IAM Policy to Lambda Role
resource "aws_iam_role_policy_attachment" "lambda_attach" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = aws_iam_policy.lambda_policy.arn
}

# Create Lambda Permission
resource "aws_lambda_permission" "allow_cloudwatch" {
  statement_id  = "AllowExecutionFromCloudWatch"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.code.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.daily_run.arn
}
