  name        = "lambda-exec-cron"
  description = "Execution role for the Lambda function"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  tags = local.default_tags
}

# Create a Lambda function
resource "aws_lambda_function" "cron" {
  filename      = "./supplement/lambda_func.zip"
  function_name = "cron"
  handler       = "index.handler"
  runtime       = "nodejs14.x"

  role = aws_iam_role.lambda_exec.arn

  depends_on = []
}

# Create an IAM policy for the Lambda function
resource "aws_iam_policy" "lambda_exec" {
  name        = "lambda-exec-cron"
  description = "Execution policy for the Lambda function"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "lambda:InvokeFunction"
        Effect = "Allow"
        Resource = aws_lambda_function.cron.arn
      }
    ]
  })
}

# Attach the IAM policy to the Lambda execution role
resource "aws_iam_role_policy_attachment" "lambda-exec-attach" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = aws_iam_policy.lambda_exec.arn
}

# Create an EventBridge event rule
resource "aws_cloudwatch_event_rule" "cron" {
  name        = "cron"
  description = "EventBridge event rule for the Lambda function"

  schedule_expression = "cron(0 7 * * ? *)"
}

# Create an EventBridge event target
resource "aws_cloudwatch_event_target" "lambda" {
  target_id = "lambda"
  rule      = aws_cloudwatch_event_rule.cron.name
  arn       = aws_lambda_function.cron.arn

  depends_on = []
}
