resource "aws_iam_role" "cloudfront_role" {
  name        = "cloudfront-role"
  description = "Role for the CloudFront distribution"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
      }
    ]
  })
}

# Create the IAM policy for the CloudFront distribution
data "aws_iam_policy_document" "cloudfront_policy" {
  statement {
    sid       = "GrantCloudFrontPermissions"
    effect    = "Allow"
    actions   = ["s3:GetObject"]
    resources = [aws_s3_bucket.video_bucket.arn]
  }
}

# Create the IAM policy
resource "aws_iam_policy" "cloudfront_policy" {
  name        = "cloudfront-policy"
  description = "Policy for the CloudFront distribution"
  policy      = data.aws_iam_policy_document.cloudfront_policy.jsonencode()
}

# Attach the IAM policy to the CloudFront role
resource "aws_iam_role_policy_attachment" "cloudfront_policy_attachment" {
  role       = aws_iam_role.cloudfront_role.name
  policy_arn = aws_iam_policy.cloudfront_policy.arn
}

# Define the CloudFront distribution
resource "aws_cloudfront_distribution" "video_distribution" {
  origin {
    domain_name = aws_s3_bucket.video_bucket.bucket_regional_domain_name
    origin_id   = "video-bucket"

    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "http-only"
      origin_ssl_protocols   = ["TLSv1.2"]
