      {
        allowed_methods = ["GET", "HEAD"]
        cached_methods  = ["GET", "HEAD"]
        path_pattern    = "*"

        forwarded_values = {
          query_string = false
        }
      }
    ]
    signing_behavior = "option-all"
    signing_protocol = "aws SIGv4"
  })
}

