terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.0" }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  type    = string
  default = "us-east-1"
}

locals {
  default_tags = {
    Owner       = "iac-eval"
    Environment = "dev"
    CostCenter  = "1234"
  }
}

# Create VPC
resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true
  tags                 = local.default_tags
}

# Create public subnets
resource "aws_subnet" "public" {
  count             = 2
  vpc_id            = aws_vpc.example.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"
  map_public_ip_on_launch = true
  tags = local.default_tags
}

# Create security group for database access
resource "aws_security_group" "database" {
  name        = "database-sg"
  description = "Database access security group"
  vpc_id      = aws_vpc.example.id

  # Allow incoming traffic on PostgreSQL port
  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.example.cidr_block]
  }

  # Allow outgoing traffic on all ports
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.example.cidr_block]
  }

  tags = local.default_tags
}

# Create PostgreSQL database instance
resource "aws_db_instance" "example" {
  identifier             = "postgresql-identifier"
  instance_class         = "db.r5.xlarge"
  allocated_storage      = 5
  storage_type           = "gp2"
  engine                 = "postgres"
  engine_version         = "17.1"
  username               = "myuser"
  password               = "mypassword"
  vpc_security_group_ids = [aws_security_group.database.id]
  db_subnet_group_name   = aws_db_subnet_group.example.id
  skip_final_snapshot    = true
  tags                   = local.default_tags
}

resource "aws_db_subnet_group" "example" {
  name       = "mydb-subnet-group"
  subnet_ids = aws_subnet.public.*.id
}

output "rds_instance_identifier" {
  value = aws_db_instance.example.identifier
}
