  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  type    = string
  default = "us-east-1"
}

locals {
  default_tags = {
    Owner       = "iac-eval"
    Environment = "dev"
    CostCenter  = "1234"
  }
}

# Create a KMS key for database encryption
resource "aws_kms_key" "db_encryption_key" {
  description             = "KMS key for database encryption"
  deletion_window_in_days = 10
  tags                    = local.default_tags
}

# Create a custom parameter group for PostgreSQL
resource "aws_db_parameter_group" "pg_param_group" {
  name        = "custom-pg-param-group"
  family      = "postgres14"
  description = "Custom parameter group for PostgreSQL 14"

  tags = local.default_tags

  # Create a parameter for 'shared_buffers'
  parameter {
    name  = "shared_buffers"
    value = "128MB"
  }

  # Create a parameter for 'effective_cache_size'
  parameter {
    name  = "effective_cache_size"
    value = "512MB"
  }

  # Create a parameter for 'maintenance_work_mem'
  parameter {
    name  = "maintenance_work_mem"
    value = "256MB"
  }
}

# Create a security group for the database
resource "aws_security_group" "db_sg" {
  name        = "db-sg"
  description = "Security group for the database"
  vpc_id      = aws_vpc.db_vpc.id

  tags = local.default_tags

  # Allow incoming traffic on port 5432
  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }
}

# Create a VPC for the database
resource "aws_vpc" "db_vpc" {
  cidr_block = "10.0.0.0/16"

  tags = local.default_tags
}

# Create a subnet for the database
resource "aws_subnet" "db_subnet" {
  vpc_id     = aws_vpc.db_vpc.id
  cidr_block = "10.0.1.0/24"

  availability_zone = "us-east-1a"

  tags = local.default_tags
}

# Create an RDS instance for the database
resource "aws_db_instance" "db_instance" {
  identifier             = "db-instance"
  allocated_storage      = 20
  engine                 = "postgres"
  instance_class         = "db.t2.micro"
  db_name                = "mydb"
  username               = "dbadmin"
  password               = "password"
  parameter_group_name   = aws_db_parameter_group.pg_param_group.name
  vpc_security_group_ids = [aws_security_group.db_sg.id]
  publicly_accessible    = false
  skip_final_snapshot    = true
  multi_az               = true
  storage_encrypted      = true
  kms_key_id             = aws_kms_key.db_encryption_key.arn

  tags = local.default_tags
}

# Create an S3 bucket for database backups
resource "aws_s3_bucket" "db_backups" {
  bucket = "db-backups"
  acl    = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  tags = local.default_tags
}

# Create a KMS key for S3 bucket encryption
resource "aws_kms_key" "s3_encryption_key" {
  description             = "KMS key for S3 bucket encryption"
  deletion_window_in_days = 10
  tags                    = local.default_tags
}

