terraform {
  required_version = ">= 1.5.0"

  # Define AWS Provider
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Define AWS Provider with Region
provider "aws" {
  region = var.region
}

# Define the Variable for the Region
variable "region" {
  type    = string
  default = "us-east-1"
}

# Create a Main VPC with Two Subnets Across Different Availability Zones
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name        = "main-vpc"
    Environment = "dev"
  }
}

resource "aws_subnet" "subnet1" {
  cidr_block = "10.0.1.0/24"
  vpc_id     = aws_vpc.main.id
  availability_zone = "us-east-1a"
  tags = {
    Name        = "subnet-1"
    Environment = "dev"
  }
}

resource "aws_subnet" "subnet2" {
  cidr_block = "10.0.2.0/24"
  vpc_id     = aws_vpc.main.id
  availability_zone = "us-east-1b"
  tags = {
    Name        = "subnet-2"
    Environment = "dev"
  }
}

# Create a Security Group to Allow Database Access
resource "aws_security_group" "database" {
  vpc_id = aws_vpc.main.id
  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
  tags = {
    Name        = "database-sg"
    Environment = "dev"
  }
}

# Create a MySQL RDS Instance with Public Accessibility
resource "aws_db_instance" "mysql" {
  identifier             = "mysql-rds"
  allocated_storage      = 20
  engine                 = "mysql"
  instance_class         = "db.t2.micro"
  db_name                = "mysql-rds"
  username               = "dbadmin"
  password               = var.db_password
  vpc_security_group_ids = [aws_security_group.database.id]
  publicly_accessible    = true
  skip_final_snapshot    = true
  tags = {
    Name        = "mysql-rds"
    Environment = "dev"
  }
}

# Output the Database Endpoint
output "mysql_endpoint" {
  value = aws_db_instance.mysql.endpoint
}

# Define a Variable for the DB Password
variable "db_password" {
  type      = string
  sensitive = true
  default   = "your_password_here"
}

locals {
  default_tags = {
    Owner       = "iac-eval"
    Environment = "dev"
    CostCenter  = "1234"
  }
}

resource "aws_db_subnet_group" "database" {
  name       = "database-subnet-group"
  subnet_ids = [aws_subnet.subnet1.id, aws_subnet.subnet2.id]

  tags = local.default_tags
}
