    option_settings {
      name  = "TDE_CREDENTIALS_ARN"
      value = "arn:aws:secretsmanager:us-east-1:123456789012:secret/my-rds-tde-credentials"
    }

    option_settings {
      name  = "TDE_STATUS"
      value = "ENABLED"
    }
  }
}

resource "aws_iam_role" "my-rds-execution-role" {
  name        = "my-rds-execution-role"
  description = "Execution role for RDS"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy" "my-rds-execution-role-policy" {
  name   = "my-rds-execution-role-policy"
  role   = aws_iam_role.my-rds-execution-role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
        ]
        Effect = "Allow"
        Resource = aws_s3_bucket.my-s3-bucket.arn
      },
    ]
  })
}

resource "aws_s3_bucket" "my-s3-bucket" {
  bucket = var.s3-bucket-name
  acl    = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

output "s3_bucket_arn" {
  value = aws_s3_bucket.my-s3-bucket.arn
}
