  vpc_id            = aws_vpc.example.id
  availability_zone = "us-east-1a"
  tags              = local.default_tags
}

# Create a security group
resource "aws_security_group" "example" {
  name   = "allow-rds-ingress"
  vpc_id = aws_vpc.example.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = local.default_tags
}

# Create an IAM role for the RDS instance
resource "aws_iam_role" "example" {
  name               = "rds-iam-role"
  description        = "RDS IAM role for enhanced connection management"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.default_tags
}

# Create an IAM policy for the Secrets Manager
resource "aws_iam_policy" "example" {
  name        = "secrets-manager-policy"
  description = "Policy for Secrets Manager"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret"
        ]
        Resource = aws_secretsmanager_secret.example.arn
      }
    ]
  })

  tags = local.default_tags
}

# Create a Secrets Manager secret
resource "aws_secretsmanager_secret" "example" {
  name = "mysecret"
}

# Create an RDS Aurora MySQL cluster
resource "aws_rds_cluster" "example" {
  cluster_identifier = "aurora-mysql-cluster"
  engine             = "aurora-mysql"
  instance_class     = "db.r5.large"
  database_name      = "mydb"
  master_username    = "myuser"
  master_password    = "mypassword"
  vpc_security_group_ids = [aws_security_group.example.id]
  db_subnet_group_name = aws_db_subnet_group.example.name
  iam_database_authentication_enabled = true
  tags = local.default_tags
}

# Create a DB subnet group
resource "aws_db_subnet_group" "example" {
  name       = "example-subnet-group"
  description = "Subnet group for the RDS cluster"
  subnet_ids = [aws_subnet.example[0].id, aws_subnet.example[1].id]
  tags       = local.default_tags
}

# Create a proxy for the RDS cluster
resource "aws_rds_cluster_proxy" "example" {
  db_cluster_identifier = aws_rds_cluster.example.id
  role_arn              = aws_iam_role.example.arn
  vpc_security_group_ids = [aws_security_group.example.id]
  vpc_subnet_ids         = [aws_subnet.example[0].id, aws_subnet.example[1].id]
  tags = local.default_tags

  auth {
    auth_scheme = "SECRETS"
    description = "RDS for MySQL databases, specify `MYSQL`"
    secret_arn = aws_secretsmanager_secret.example.arn
  }
}
