    aws = { source = "hashicorp/aws", version = "~> 5.0" }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  type    = string
  default = "us-east-1"
}

locals {
  default_tags = {
    Owner       = "iac-eval"
    Environment = "dev"
    CostCenter  = "1234"
  }
}

resource "aws_sns_topic" "glacier_sns_topic" {
  name = "glacier-sns-topic"
}

data "aws_iam_policy_document" "my_archive" {
  statement {
    sid    = "add-read-only-perm"
    effect = "Allow"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = [
      "glacier:InitiateJob",
      "glacier:GetJobOutput",
    ]

    resources = ["arn:aws:glacier:eu-west-1:432981146916:vaults/MyArchive"]
  }
}

resource "aws_glacier_vault" "my_archive" {
  name = "MyArchive"

  notification {
    sns_topic = aws_sns_topic.glacier_sns_topic.arn
    events    = ["ArchiveRetrievalCompleted", "InventoryRetrievalCompleted"]
  }

  access_policy = data.aws_iam_policy_document.my_archive.json

  tags = local.default_tags
}

resource "aws_sns_topic_policy" "topic_policy" {
  arn = aws_sns_topic.glacier_sns_topic.arn
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyUnsubscribe"
        Effect    = "Deny"
        Principal = "*"
        Action     = "SNS:Unsubscribe"
        Resource  = aws_sns_topic.glacier_sns_topic.arn
      }
    ]
  })
}

resource "aws_s3_bucket" "s3_bucket" {
  bucket = "glacier-s3-bucket"
  acl    = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  tags = local.default_tags
}

resource "aws_s3_bucket_notification" "bucket_notification" {
  bucket = aws_s3_bucket.s3_bucket.id

  topic {
    topic_arn     = aws_sns_topic.glacier_sns_topic.arn
    events        = ["s3:ObjectCreated:*"]
    filter_suffix = ".log"
  }
}
