  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.0" }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  type    = string
  default = "us-east-1"
}

locals {
  default_tags = {
    Owner       = "iac-eval"
    Environment = "dev"
    CostCenter  = "1234"
  }
}

# Create a Cognito User Pool
resource "aws_cognito_user_pool" "pool" {
  name       = "authenticate-cognito"
  username_configuration {
    case_sensitive = false
  }

  tags = local.default_tags
}

# Create a Cognito Client
resource "aws_cognito_user_pool_client" "client" {
  name             = "authenticate-cognito"
  user_pool_id     = aws_cognito_user_pool.pool.id
  generate_secret  = true

  allowed_oauth_flows_user_pool_client = true
}

# Create an IAM Role for the Load Balancer
resource "aws_iam_role" "load_balancer" {
  name               = "authenticate-cognito-lb"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancer.amazonaws.com"
        }
      }
    ]
  })

  tags = local.default_tags
}

# Create an IAM Policy for the Load Balancer
resource "aws_iam_policy" "load_balancer" {
  name        = "authenticate-cognito-lb"
  description = "Policy for the Load Balancer"

  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "cognito-idp:GetUserPoolClient"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the IAM Policy to the IAM Role
resource "aws_iam_role_policy_attachment" "load_balancer" {
  role       = aws_iam_role.load_balancer.name
  policy_arn = aws_iam_policy.load_balancer.arn
}

# Create a Load Balancer
resource "aws_elb" "authenticate" {
  name               = "authenticate-cognito-lb"
  subnets            = [aws_subnet.example.id]
  security_groups    = [aws_security_group.example.id]
  instances          = []

  listener {
    instance_port     = 80
    instance_protocol = "http"
    lb_port           = 80
    lb_protocol       = "http"
  }

  health_check {
    healthy_threshold   = 3
    unhealthy_threshold = 10
    timeout             = 5
    target              = "HTTP:80/"
    interval            = 30
  }

  tags = local.default_tags
}

# Create a subnet
resource "aws_subnet" "example" {
  cidr_block = "10.0.1.0/24"
  vpc_id     = aws_vpc.example.id
  availability_zone = "us-east-1a"

  tags = local.default_tags
}

# Create a security group
resource "aws_security_group" "example" {
  name        = "example-sg"
  description = "Security group for the Load Balancer"
  vpc_id      = aws_vpc.example.id

  tags = local.default_tags
}

# Create a VPC
resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"

  tags = local.default_tags
}
