    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "region" {
  type    = string
  default = "us-east-1"
}

locals {
  default_tags = {
    Owner       = "iac-eval"
    Environment = "dev"
    CostCenter  = "1234"
  }
}

# Create a VPC
resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"

  tags = local.default_tags
}

# Create subnets
resource "aws_subnet" "example_1" {
  vpc_id            = aws_vpc.example.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"

  tags = local.default_tags
}

resource "aws_subnet" "example_2" {
  vpc_id            = aws_vpc.example.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-east-1b"

  tags = local.default_tags
}

# Create an internet gateway
resource "aws_internet_gateway" "example" {
  vpc_id = aws_vpc.example.id

  tags = local.default_tags
}

# Create a route table for internet access
resource "aws_route_table" "example" {
  vpc_id = aws_vpc.example.id

  tags = local.default_tags
}

# Create a route to the internet gateway
resource "aws_route" "example" {
  route_table_id         = aws_route_table.example.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.example.id
}

# Create a security group
resource "aws_security_group" "example" {
  name        = "allow-mysql-and-postgresql"
  description = "Allow access to MySQL and PostgreSQL databases"
  vpc_id      = aws_vpc.example.id

  tags = local.default_tags

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create a database subnet group
resource "aws_db_subnet_group" "example" {
  name       = "example-subnet-group"
  description = "example subnet group"
  subnet_ids = [aws_subnet.example_1.id, aws_subnet.example_2.id]
}

# Fix the aws_security_group_rule resource to remove the incorrect egress rule
resource "aws_security_group_rule" "example" {
  security_group_id = aws_security_group.example.id
  type              = "ingress"
  from_port         = 3306
  to_port           = 3306
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
}

resource "aws_security_group_rule" "example_postgresql" {
  security_group_id = aws_security_group.example.id
  type              = "ingress"
  from_port         = 5432
  to_port           = 5432
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
}
