  type    = string
  default = "us-east-1"
}

locals {
  default_tags = {
    Owner       = "iac-eval"
    Environment = "dev"
    CostCenter  = "1234"
  }
}

resource "aws_vpc" "mainvpc" {
  cidr_block = "10.0.0.0/16"
  tags       = local.default_tags
}

resource "aws_network_acl" "main" {
  vpc_id = aws_vpc.mainvpc.id

  egress {
    protocol   = "tcp"
    rule_no    = 200
    action     = "allow"
    cidr_block = "10.3.0.0/18"
    from_port  = 443
    to_port    = 443
  }

  ingress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "10.3.0.0/18"
    from_port  = 80
    to_port    = 80
  }
}

resource "aws_network_acl_rule" "example" {
  network_acl_id = aws_network_acl.main.id
  rule_number    = 300
  egress          = true
  action          = "allow"
  cidr_block      = "10.3.0.0/18"
  from_port       = 443
  to_port         = 443
}

resource "aws_network_acl_rule" "example_in" {
  network_acl_id = aws_network_acl.main.id
  rule_number    = 400
  ingress         = true
  action          = "allow"
  cidr_block      = "10.3.0.0/18"
  from_port       = 80
  to_port         = 80
}
